using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using UnscRelay.Core;
namespace UnscRelay.App;
public partial class MainWindow
{
 sealed record KeyInstallationIntent(long Generation,SshSession Session,string ProfileHash,string KeyId,PublicKeyInstallationPreview Preview,DateTimeOffset Expires);
 readonly Dictionary<Guid,KeyInstallationIntent> keyInstallationPlans=[];
 readonly Dictionary<Guid,CancellationTokenSource> keyInstallationRuns=[];
 readonly Dictionary<CancellationTokenSource,string> keyInstallationPreviewStops=[];
 void CancelKeyInstallations(){keyInstallationPlans.Clear();foreach(var operation in keyInstallationRuns.Values.Concat(keyInstallationPreviewStops.Keys).ToArray())try{operation.Cancel();}catch(Exception error)when(error is ObjectDisposedException or AggregateException){}}
 void CancelSessionKeyInstallations(string sessionId){foreach(var pair in keyInstallationPlans.Where(pair=>pair.Value.Session.Id==sessionId).ToArray()){if(keyInstallationRuns.TryGetValue(pair.Key,out var running))running.Cancel();else keyInstallationPlans.Remove(pair.Key);}foreach(var pair in keyInstallationPreviewStops.Where(pair=>pair.Value==sessionId).ToArray())pair.Key.Cancel();}
 void ClearOperationPlans(){bridgePlans.Clear();CancelKeyInstallations();}
 void LockVault(){CancelKeyInstallations();vault.Lock();Emit("vaultLocked",new{});}

 Func<string,bool>? keyInstallationTestConsent;
 static string InstallationProfileHash(ConnectionProfile profile)=>Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(profile,ProfileStore.Json)));
 void CheckKeyInstallation(KeyInstallationIntent intent){RequireOperationSession(intent.Generation);if(!vault.IsUnlocked||!sessions.TryGetValue(intent.Session.Id,out var current)||!ReferenceEquals(current,intent.Session)||!current.FilesAvailable)throw new IOException("La sessione SSH o l’archivio non sono più disponibili.");var profile=data.Profiles.SingleOrDefault(profile=>profile.Id==intent.Session.Profile.Id);if(profile==null||InstallationProfileHash(profile)!=intent.ProfileHash)throw new IOException("Il profilo è cambiato. Ripeti l’anteprima.");var key=vault.List().SingleOrDefault(key=>key.Id==intent.KeyId);if(key==null||key.Kind!="ssh-key"||key.Certificate!=null||NativeIdentity.Parse(key.PublicKey).PublicKey!=intent.Preview.PublicKey)throw new IOException("La chiave selezionata è cambiata. Ripeti l’anteprima.");}
 async Task<object?> PublicKeyInstallationAction(string action,JsonElement p){
  var generation=authenticationGeneration;RequireOperationSession(generation);foreach(var old in keyInstallationPlans.Where(pair=>pair.Value.Generation!=generation||pair.Value.Expires<=DateTimeOffset.UtcNow&&!keyInstallationRuns.ContainsKey(pair.Key)).Select(pair=>pair.Key).ToArray())keyInstallationPlans.Remove(old);
  if(action=="keyInstallCancel"){var id=p.GetProperty("id").GetGuid();if(!keyInstallationPlans.TryGetValue(id,out var intent)||intent.Generation!=generation)return false;if(keyInstallationRuns.TryGetValue(id,out var running))running.Cancel();else keyInstallationPlans.Remove(id);return true;}
  if(!vault.IsUnlocked)throw new InvalidOperationException("Sblocca prima l’archivio chiavi.");
  if(action=="keyInstallKeys")return vault.List().Where(key=>key.Kind=="ssh-key"&&key.Certificate==null&&key.PublicKey.Length>0).Select(key=>new{key.Id,key.Name,fingerprint=NativeIdentity.Parse(key.PublicKey).Fingerprint}).ToArray();
  if(action=="keyInstallPreview"){
   if(keyInstallationPlans.Count>=20)throw new IOException("Attendi la scadenza delle anteprime precedenti.");var session=Session(p);if(session.Profile.Protocol is not("ssh" or "sftp")||!session.FilesAvailable)throw new IOException("La procedura richiede una sessione SSH/SFTP del motore integrato.");var profile=data.Profiles.SingleOrDefault(profile=>profile.Id==session.Profile.Id)??throw new IOException("Salva prima il profilo della connessione.");var key=vault.List().SingleOrDefault(key=>key.Id==S(p,"keyId"))??throw new IOException("Chiave non disponibile.");if(key.Kind!="ssh-key"||key.Certificate!=null)throw new IOException("Seleziona una chiave software senza certificato.");using var stop=CancellationTokenSource.CreateLinkedTokenSource(accountOperationStop.Token);stop.CancelAfter(TimeSpan.FromSeconds(25));var profileHash=InstallationProfileHash(profile);if(profileHash!=InstallationProfileHash(session.Profile))throw new IOException("Riapri la connessione dopo aver modificato il suo profilo.");keyInstallationPreviewStops.Add(stop,session.Id);PublicKeyInstallationPreview preview;try{preview=await session.PreparePublicKeyInstallationAsync(key.PublicKey,stop.Token);}finally{keyInstallationPreviewStops.Remove(stop);}RequireOperationSession(generation);var id=Guid.NewGuid();var intent=new KeyInstallationIntent(generation,session,profileHash,key.Id,preview,DateTimeOffset.UtcNow.AddMinutes(5));CheckKeyInstallation(intent);keyInstallationPlans[id]=intent;return new{id,preview};
  }
  var planId=p.GetProperty("id").GetGuid();if(!keyInstallationPlans.TryGetValue(planId,out var plan)||plan.Expires<=DateTimeOffset.UtcNow)throw new IOException("Anteprima scaduta. Ripeti la verifica.");CheckKeyInstallation(plan);if(keyInstallationRuns.Count>0)throw new IOException("Attendi la verifica della chiave già in corso.");var passphrase=S(p,"passphrase");if(passphrase.Length>8192||passphrase.Contains('\0'))throw new ArgumentException("Passphrase non valida.");
  if(!plan.Preview.AlreadyPresent){var review=NativeText("Installare questa chiave pubblica senza rimuovere gli accessi esistenti?")+"\n\n"+plan.Session.Profile.Name+"\n"+plan.Session.Profile.Username+"@"+plan.Session.Profile.Host+":"+plan.Session.Profile.Port+"\n"+plan.Preview.Path+"\n"+plan.Preview.Fingerprint+"\n\n"+NativeText("Il profilo resta invariato. La prova successiva usa solo la nuova chiave e non apre shell o comandi.");if(!(filesSmokeTest&&keyInstallationTestConsent!=null?keyInstallationTestConsent(review):Confirm(review)))throw new OperationCanceledException();ConfirmProductionOperation(plan.Session.Profile,"Installazione chiave pubblica SSH",resource:plan.Preview.Path);CheckKeyInstallation(plan);}
  using var operation=CancellationTokenSource.CreateLinkedTokenSource(accountOperationStop.Token);operation.CancelAfter(TimeSpan.FromMinutes(2));keyInstallationRuns.Add(planId,operation);var probeId=Guid.NewGuid().ToString("N");try{
   var installed=await plan.Session.InstallPublicKeyAsync(plan.Preview,operation.Token);CheckKeyInstallation(plan);var probeProfile=plan.Session.Profile with{Id=probeId,Protocol="ssh",Authentication="key",KeyId=plan.KeyId,PasswordId="",KeyboardFallback=false,Hooks=[],Tunnels=[]};connectionPassphrases[probeId]=passphrase;passphrase="";
   try{using var probe=await SshRoutes.CreateAsync(probeProfile,data.Profiles,async(profile,host,port)=>{RequireOperationSession(generation);var result=await CreateAuthenticatedSession(profile,host,port,Guid.NewGuid().ToString("N"),automatic:true);try{RequireOperationSession(generation);return result;}catch{result.Dispose();throw;}},operation.Token);await probe.VerifyKeyAuthenticationAsync(operation.Token);CheckKeyInstallation(plan);return new{installed=true,verified=true,alreadyPresent=installed.AlreadyPresent,path=installed.Path,message=NativeText("Nuovo accesso verificato con la sola chiave. Il profilo e i vecchi accessi non sono stati modificati.")};}
   catch(Exception error)when(!operation.IsCancellationRequested&&generation==authenticationGeneration&&error is not OutOfMemoryException){RequireOperationSession(generation);return new{installed=true,verified=false,alreadyPresent=installed.AlreadyPresent,path=installed.Path,message=NativeText("La chiave è presente sul server, ma il nuovo accesso non è stato verificato. Il profilo e i vecchi accessi restano invariati.")};}
  }finally{connectionPassphrases.Remove(probeId);keyInstallationRuns.Remove(planId);keyInstallationPlans.Remove(planId);}
 }
}
